{"file_text": "@namespace sv_eaf171920d2e4ef788c283567e9ee8fa.Components.Pages.Apply
@using sv_eaf171920d2e4ef788c283567e9ee8fa.Models

<div class="references-step">
    <h3>References</h3>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="reference-card">
            <div class="reference-header">
                <h5>Reference @(index + 1)</h5>
                @if (References.Count > 2)
                {
                    <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" class="form-control" value="@References[index].Name"
                       @onchange="e => UpdateReference(index, References[index] with { Name = e.Value?.ToString() ?? "" })" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" class="form-control" value="@References[index].Relationship"
                       @onchange="e => UpdateReference(index, References[index] with { Relationship = e.Value?.ToString() ?? "" })" />
            </div>

            <div class="form-row">
                <div class="form-group half">
                    <label>Email *</label>
                    <input type="email" class="form-control" value="@References[index].Email"
                           @onchange="e => UpdateReference(index, References[index] with { Email = e.Value?.ToString() ?? "" })" />
                </div>
                <div class="form-group half">
                    <label>Phone *</label>
                    <input type="tel" class="form-control" value="@References[index].Phone"
                           @onchange="e => UpdateReference(index, References[index] with { Phone = e.Value?.ToString() ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-outline-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}
