@namespace sv_eaf171920d2e4ef788c283567e9ee8fa.Components.Pages.Apply

<div class="cover-letter-step">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea class="form-control cover-letter-textarea" rows="12"
                  @bind="CoverLetterText" @bind:event="oninput"
                  maxlength="2000"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(CoverLetterText.Length > 1800 ? "warning" : "")">
            @CoverLetterText.Length / 2000 characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }
