@page "/apply"
@namespace sv_eaf171920d2e4ef788c283567e9ee8fa.Components.Pages.Apply
@using sv_eaf171920d2e4ef788c283567e9ee8fa.Models
@using sv_eaf171920d2e4ef788c283567e9ee8fa.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        Work="@GetWorkHistory()"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="NavigateToStep"
                        OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntry> workEntries = new() { new("", "", DateTime.Today, null, "") };

    // Step 3 state
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step >= 0 && step < currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);
    private WorkHistory GetWorkHistory() => new(workEntries);

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(GetPersonalInfo(), GetWorkHistory(), references, coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

/* Shared form styles */
:deep(.form-group) {
    margin-bottom: 1rem;
}

:deep(.form-group label) {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

:deep(.form-control) {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

:deep(.form-control:focus) {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

:deep(.form-row) {
    display: flex;
    gap: 1rem;
}

:deep(.form-group.half) {
    flex: 1;
}

:deep(.checkbox-group) {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

:deep(.step-buttons) {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

:deep(.btn) {
    padding: 0.5rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    text-decoration: none;
}

:deep(.btn-primary) {
    background: #0d6efd;
    color: #fff;
}

:deep(.btn-primary:hover) {
    background: #0b5ed7;
}

:deep(.btn-secondary) {
    background: #6c757d;
    color: #fff;
}

:deep(.btn-secondary:hover) {
    background: #5c636a;
}

:deep(.btn-success) {
    background: #198754;
    color: #fff;
}

:deep(.btn-success:hover) {
    background: #157347;
}

:deep(.btn-lg) {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

:deep(.btn-outline-secondary) {
    background: transparent;
    border: 1px solid #6c757d;
    color: #6c757d;
}

:deep(.btn-outline-secondary:hover) {
    background: #6c757d;
    color: #fff;
}

:deep(.btn-outline-danger) {
    background: transparent;
    border: 1px solid #dc3545;
    color: #dc3545;
}

:deep(.btn-outline-danger:hover) {
    background: #dc3545;
    color: #fff;
}

:deep(.btn-link) {
    background: transparent;
    color: #0d6efd;
    padding: 0;
    text-decoration: underline;
}

:deep(.btn[disabled]) {
    opacity: 0.6;
    cursor: not-allowed;
}

:deep(.validation-error) {
    color: #dc3545;
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 0.5rem 0.75rem;
    margin-top: 1rem;
