toolArgs.file_text:
.apply-page {
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

/* Shared form styles */
:deep(.form-group) {
    margin-bottom: 1rem;
}

:deep(.form-group label) {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

:deep(.form-control) {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

:deep(.form-control:focus) {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

:deep(.form-row) {
    display: flex;
    gap: 1rem;
}

:deep(.form-group.half) {
    flex: 1;
}

:deep(.checkbox-group) {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

:deep(.step-buttons) {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

:deep(.btn) {
    padding: 0.5rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    text-decoration: none;
}

:deep(.btn-primary) {
    background: #0d6efd;
    color: #fff;
}

:deep(.btn-primary:hover) {
    background: #0b5ed7;
}

:deep(.btn-secondary) {
    background: #6c757d;
    color: #fff;
}

:deep(.btn-secondary:hover) {
    background: #5c636a;
}

:deep(.btn-success) {
    background: #198754;
    color: #fff;
}

:deep(.btn-success:hover) {
    background: #157347;
}

:deep(.btn-lg) {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

:deep(.btn-outline-secondary) {
    background: transparent;
    border: 1px solid #6c757d;
    color: #6c757d;
}

:deep(.btn-outline-secondary:hover) {
    background: #6c757d;
    color: #fff;
}

:deep(.btn-outline-danger) {
    background: transparent;
    border: 1px solid #dc3545;
    color: #dc3545;
}

:deep(.btn-outline-danger:hover) {
    background: #dc3545;
    color: #fff;
}

:deep(.btn-link) {
    background: transparent;
    color: #0d6efd;
    padding: 0;
    text-decoration: underline;
}

:deep(.btn[disabled]) {
    opacity: 0.6;
    cursor: not-allowed;
}

:deep(.validation-error) {
    color: #dc3545;
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 0.5rem 0.75rem;
    margin-top: 1rem;
    font-size: 0.9rem;
}

:deep(.field-error) {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

:deep(.hint) {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Work entry editor */
:deep(.work-entry-editor) {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

:deep(.entry-header) {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

:deep(.entry-header h5) {
    margin: 0;
}

/* Reference card */
:deep(.reference-card) {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

:deep(.reference-header) {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

:deep(.reference-header h5) {
    margin: 0;
}

/* Cover letter */
:deep(.cover-letter-textarea) {
    resize: vertical;
    min-height: 200px;
}

:deep(.char-count) {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

:deep(.char-count.warning) {
    color: #dc3545;
    font-weight: 500;
}

/* Review step */
:deep(.review-section) {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

:deep(.section-header) {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

:deep(.section-header h4) {
    margin: 0;
    font-size: 1.1rem;
}

:deep(.review-section dl) {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

:deep(.review-section dt) {
    font-weight: 500;
    color: #555;
}

:deep(.review-section dd) {
    margin: 0;
}

:deep(.work-review-entry) {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

:deep(.work-review-entry:last-child) {
    border-bottom: none;
}

:deep(.dates) {
    font-size: 0.85rem;
    color: #666;
}

:deep(.description) {
    margin: 0.25rem 0 0;
    font-size: 0.9rem;
    color: #444;
}

:deep(.reference-review-entry) {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

:deep(.reference-review-entry:last-child) {
    border-bottom: none;
}

:deep(.cover-letter-preview) {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

:deep(.confirmation) {
    text-align: center;
    padding: 2rem;
    background: #d1e7dd;
    border: 1px solid #badbcc;
    border-radius: 8px;
}

:deep(.confirmation h4) {
    color: #0f5132;
    margin-bottom: 1rem;
}

